#!/bin/bash
set -euo pipefail

cd /home/caliptra-rtl

TEST_NAME="kv_read_client_error_latch"
WORK_DIR="/home/caliptra-rtl/.hwe_bench/${TEST_NAME}"
TB_SV="${WORK_DIR}/tb_${TEST_NAME}.sv"
BUILD_LOG="${WORK_DIR}/build.log"
RUN_LOG="${WORK_DIR}/run.log"
SIM_BIN=""

rm -rf "${WORK_DIR}"
mkdir -p "${WORK_DIR}"

cat > "${TB_SV}" <<'SV'
`timescale 1ns/1ps

module tb_kv_read_client_error_latch;
  import kv_defines_pkg::*;

  logic clk = 0;
  logic rst_b = 0;
  logic zeroize = 0;
  kv_read_ctrl_reg_t read_ctrl_reg;
  kv_read_filter_metrics_t read_metrics;
  kv_read_t kv_read;
  kv_rd_resp_t kv_resp;
  logic write_en;
  logic [1:0] write_offset;
  logic [31:0] write_data;
  kv_error_code_e error_code;
  logic kv_ready;
  logic read_done;

  kv_read_client #(
    .DATA_WIDTH(128)
  ) dut (
    .clk(clk),
    .rst_b(rst_b),
    .zeroize(zeroize),
    .read_ctrl_reg(read_ctrl_reg),
    .read_metrics(read_metrics),
    .kv_read(kv_read),
    .kv_resp(kv_resp),
    .write_en(write_en),
    .write_offset(write_offset),
    .write_data(write_data),
    .error_code(error_code),
    .kv_ready(kv_ready),
    .read_done(read_done)
  );

  always #5 clk = ~clk;

  task automatic log_state(input string tag);
    begin
      #1;
      $display("TB_STATE %0t %s read_en=%0b write_en=%0b write_offset=%0d last=%0b resp_err=%0b error_code=0x%0h read_done=%0b",
               $time, tag, read_ctrl_reg.read_en, write_en, write_offset, kv_resp.last, kv_resp.error, error_code, read_done);
    end
  endtask

  initial begin
    read_ctrl_reg = '0;
    read_metrics = '0;
    kv_resp = '{error: 0, last: 0, read_data: 32'h1234_5678};

    repeat (2) @(posedge clk);
    rst_b = 1'b1;

    // Keep read_en asserted through the transfer, matching the sticky CSR-style usage.
    read_ctrl_reg.read_en = 1'b1;
    read_ctrl_reg.read_entry = 5;
    read_metrics.ocp_lock_in_progress = 1'b0;
    read_metrics.kv_read_dest = '0;
    read_metrics.kv_key_entry = 5;

    // Cycle 1: rule check registers the request.
    @(posedge clk);
    log_state("rule_check");

    // Cycle 2: client FSM moves from IDLE into RW.
    kv_resp.error = 1'b0;
    kv_resp.last = 1'b0;
    @(posedge clk);
    log_state("beat0_ok");

    // Cycle 3: inject the first read error.
    kv_resp.error = 1'b1;
    kv_resp.last = 1'b0;
    @(posedge clk);
    log_state("beat1_error");

    // Cycle 4: subsequent beat succeeds.
    kv_resp.error = 1'b0;
    kv_resp.last = 1'b0;
    @(posedge clk);
    log_state("beat2_success");

    // Cycle 5: final beat succeeds and ends the transfer.
    // Baseline RTL incorrectly clears error_code back to KV_SUCCESS on a later beat.
    kv_resp.error = 1'b0;
    kv_resp.last = 1'b1;
    @(posedge clk);
    log_state("beat3_success");

    if (error_code !== KV_READ_FAIL) begin
      $display("TB_FAIL expected error_code=0x%0h but saw 0x%0h", KV_READ_FAIL, error_code);
    end else begin
      $display("TB_PASS error_code stayed latched at KV_READ_FAIL");
    end
    $finish;
  end
endmodule
SV

