build_rc=0
run_rc=0

cd "${WORK_DIR}"

verilator --binary --sv --timing -Wall -Wno-fatal \
  --top-module "tb_${TEST_NAME}" \
  -I/home/caliptra-rtl/src/keyvault/rtl \
  -I/home/caliptra-rtl/src/caliptra_prim/rtl \
  -I/home/caliptra-rtl/src/libs/rtl \
  /home/caliptra-rtl/src/keyvault/rtl/kv_defines_pkg.sv \
  /home/caliptra-rtl/src/keyvault/rtl/kv_fsm.sv \
  /home/caliptra-rtl/src/keyvault/rtl/kv_read_rule_check.sv \
  /home/caliptra-rtl/src/keyvault/rtl/kv_read_client.sv \
  "${TB_SV}" \
  >"${BUILD_LOG}" 2>&1 || build_rc=$?

if [[ ${build_rc} -ne 0 ]]; then
  echo "TEST: ${TEST_NAME} ... FAIL"
  tail -n 40 "${BUILD_LOG}" || true
  echo "HWE_BENCH_RESULTS_END"
  exit 1
fi

SIM_BIN="$(find "${WORK_DIR}/obj_dir" -maxdepth 1 -type f -perm -111 -name 'V*' | head -n1 || true)"

if [[ -z "${SIM_BIN}" ]]; then
  echo "TEST: ${TEST_NAME} ... FAIL"
  ls -la "${WORK_DIR}/obj_dir" || true
  echo "HWE_BENCH_RESULTS_END"
  exit 1
fi

"${SIM_BIN}" >"${RUN_LOG}" 2>&1 || run_rc=$?

cat "${RUN_LOG}"

if [[ ${run_rc} -eq 0 ]] && grep -q "TB_PASS" "${RUN_LOG}" && ! grep -q "TB_FAIL" "${RUN_LOG}"; then
  echo "TEST: ${TEST_NAME} ... PASS"
  echo "HWE_BENCH_RESULTS_END"
  exit 0
fi

echo "TEST: ${TEST_NAME} ... FAIL"
echo "HWE_BENCH_RESULTS_END"
exit 1

