#!/bin/bash
set -u

cd /home/caliptra-rtl || exit 2

TB_NAME="hwe_kv_ctrl_lock_ecc_tb"
TB_FILE="/home/caliptra-rtl/src/ecc/tb/${TB_NAME}.sv"
BUILD_DIR="/home/caliptra-rtl/.hwe_kv_ctrl_lock_ecc"

cat > "${TB_FILE}" <<'EOF'
// SPDX-License-Identifier: Apache-2.0

`default_nettype none
`include "caliptra_reg_defines.svh"
`include "caliptra_reg_field_defines.svh"

module hwe_kv_ctrl_lock_ecc_tb
    import kv_defines_pkg::*;
();

  localparam ECC_CMD_SIGNING = 32'h2;
  localparam CLK_HALF_PERIOD = 5;
  localparam CLK_PERIOD = 2 * CLK_HALF_PERIOD;

  typedef logic [383:0] operand_t;

  logic clk_tb;
  logic reset_n_tb;
  logic cptra_pwrgood_tb;

  logic [31:0] haddr_i_tb;
  logic [31:0] hwdata_i_tb;
  logic hsel_i_tb;
  logic hwrite_i_tb;
  logic hready_i_tb;
  logic [1:0] htrans_i_tb;
  logic [2:0] hsize_i_tb;

  logic hresp_o_tb;
  logic hreadyout_o_tb;
  logic [31:0] hrdata_o_tb;

  kv_read_t [1:0] kv_read_tb;
  kv_write_t kv_write_tb;
  kv_rd_resp_t [1:0] kv_rd_resp_tb;
  kv_wr_resp_t kv_wr_resp_tb;
  pcr_signing_t pcr_signing_data_tb;

  logic error_intr_tb;
  logic notif_intr_tb;

  operand_t reg_read_data;
  logic [31:0] cycle_ctr;

  logic slot_valid [0:KV_NUM_KEYS-1];
  logic [31:0] slot_data [0:KV_NUM_KEYS-1][0:KV_NUM_DWORDS-1];

  localparam operand_t MSG = {
      32'hC8F518D4, 32'hF3AA1BD4, 32'h6ED56C1C, 32'h3C9E16FB,
      32'h800AF504, 32'hDB988435, 32'h48C5F623, 32'hEE115F73,
      32'hD4C62ABC, 32'h06D303B5, 32'hD90D9A17, 32'h5087290D
  };
  localparam operand_t PRIVKEY = {
      32'hF274F69D, 32'h163B0C9F, 32'h1FC3EBF4, 32'h292AD1C4,
      32'hEB3CEC1C, 32'h5A7DDE6F, 32'h80C14292, 32'h934C2055,
      32'hE087748D, 32'h0A169C77, 32'h2483ADEE, 32'h5EE70E17
  };
  localparam operand_t SIGN_R = {
      32'h871E6EA4, 32'hDDC5432C, 32'hDDAA60FD, 32'h7F055472,
      32'hD3C4DD41, 32'hA5BFB267, 32'h09E88C31, 32'h1A970935,
      32'h99A7C8F5, 32'h5B3974C1, 32'h9E4F5A7B, 32'hFC1DD2AC
  };
  localparam operand_t SIGN_S = {
      32'h3E5552DE, 32'h6403350E, 32'hE70AD74E, 32'h4B854D2D,
      32'hC4126BBF, 32'h9C153A5D, 32'h7A07BD4B, 32'h85D06E45,
      32'hF850920E, 32'h898FB7D3, 32'h4F80796D, 32'hAE29365C
  };
  localparam operand_t IV = {
      32'h3401CEFA, 32'hE20A7376, 32'h49073AC1, 32'hA351E329,
      32'h26DB9ED0, 32'hDB6B1CFF, 32'hAB0493DA, 32'hAFB93DDD,
      32'hD83EDEA2, 32'h8A803D0D, 32'h003B2633, 32'hB9D0F1BF
  };

  ecc_top #(
      .AHB_DATA_WIDTH(32),
      .AHB_ADDR_WIDTH(32)
  ) dut (
      .clk(clk_tb),
      .reset_n(reset_n_tb),
      .cptra_pwrgood(cptra_pwrgood_tb),
      .haddr_i(haddr_i_tb),
      .hwdata_i(hwdata_i_tb),
      .hsel_i(hsel_i_tb),
      .hwrite_i(hwrite_i_tb),
      .hready_i(hready_i_tb),
      .htrans_i(htrans_i_tb),
      .hsize_i(hsize_i_tb),
      .hresp_o(hresp_o_tb),
      .hreadyout_o(hreadyout_o_tb),
      .hrdata_o(hrdata_o_tb),
      .kv_read(kv_read_tb),
      .kv_write(kv_write_tb),
      .kv_rd_resp(kv_rd_resp_tb),
      .kv_wr_resp(kv_wr_resp_tb),
      .pcr_signing_data(pcr_signing_data_tb),
      .busy_o(),
      .error_intr(error_intr_tb),
      .notif_intr(notif_intr_tb),
      .debugUnlock_or_scan_mode_switch('0)
  );

  always begin
    #CLK_HALF_PERIOD;
    clk_tb = !clk_tb;
  end

  always #(CLK_PERIOD) cycle_ctr = cycle_ctr + 1;

  always_comb begin : kv_model
    kv_wr_resp_tb = '0;
    pcr_signing_data_tb = '0;
    for (int client = 0; client < 2; client++) begin
      kv_rd_resp_tb[client].error = !slot_valid[kv_read_tb[client].read_entry];
      kv_rd_resp_tb[client].last = (kv_read_tb[client].read_offset == 4'd11);
      kv_rd_resp_tb[client].read_data =
          slot_valid[kv_read_tb[client].read_entry]
              ? slot_data[kv_read_tb[client].read_entry][kv_read_tb[client].read_offset]
              : 32'h0;
    end
  end

  task automatic init_slots;
    begin
      for (int slot = 0; slot < KV_NUM_KEYS; slot++) begin
        slot_valid[slot] = 1'b0;
        for (int word = 0; word < KV_NUM_DWORDS; word++) begin
          slot_data[slot][word] = '0;
        end
      end

      slot_valid[1] = 1'b1;
      slot_data[1][0] = 32'hF274F69D;
      slot_data[1][1] = 32'h163B0C9F;
      slot_data[1][2] = 32'h1FC3EBF4;
      slot_data[1][3] = 32'h292AD1C4;
      slot_data[1][4] = 32'hEB3CEC1C;
      slot_data[1][5] = 32'h5A7DDE6F;
      slot_data[1][6] = 32'h80C14292;
      slot_data[1][7] = 32'h934C2055;
      slot_data[1][8] = 32'hE087748D;
      slot_data[1][9] = 32'h0A169C77;
      slot_data[1][10] = 32'h2483ADEE;
      slot_data[1][11] = 32'h5EE70E17;
    end
  endtask

  task automatic init_sim;
    begin
      cycle_ctr = '0;
      clk_tb = 1'b0;
      reset_n_tb = 1'b0;
      cptra_pwrgood_tb = 1'b0;
      haddr_i_tb = '0;
      hwdata_i_tb = '0;
      hsel_i_tb = '0;
      hwrite_i_tb = '0;
      hready_i_tb = '0;
      htrans_i_tb = '0;
      hsize_i_tb = 3'b011;
      init_slots();
    end
  endtask

  task automatic reset_dut;
    begin
      cptra_pwrgood_tb = 1'b0;
      reset_n_tb = 1'b0;
      #(2 * CLK_PERIOD);
      cptra_pwrgood_tb = 1'b1;
      #(2 * CLK_PERIOD);
      reset_n_tb = 1'b1;
    end
  endtask

  task automatic write_single_word(input logic [31:0] address, input logic [31:0] word);
    begin
      hsel_i_tb = 1'b1;
      haddr_i_tb = address;
      hwrite_i_tb = 1'b1;
      hready_i_tb = 1'b1;
      htrans_i_tb = 2'b10;
      hsize_i_tb = 3'b010;
      #(CLK_PERIOD);

      haddr_i_tb = 'z;
      hwdata_i_tb = word;
      hwrite_i_tb = 1'b0;
      htrans_i_tb = 2'b00;
    end
  endtask

  task automatic read_single_word(input logic [31:0] address);
    begin
      hsel_i_tb = 1'b1;
      haddr_i_tb = address;
      hwrite_i_tb = 1'b0;
      hready_i_tb = 1'b1;
      htrans_i_tb = 2'b10;
      hsize_i_tb = 3'b010;
      #(CLK_PERIOD);

      hwdata_i_tb = '0;
      haddr_i_tb = 'z;
      htrans_i_tb = 2'b00;
    end
  endtask

  task automatic write_block(input logic [31:0] addr, input operand_t block);
    begin
      write_single_word(addr + 4*0, block[383:352]);
      write_single_word(addr + 4*1, block[351:320]);
      write_single_word(addr + 4*2, block[319:288]);
      write_single_word(addr + 4*3, block[287:256]);
      write_single_word(addr + 4*4, block[255:224]);
      write_single_word(addr + 4*5, block[223:192]);
      write_single_word(addr + 4*6, block[191:160]);
      write_single_word(addr + 4*7, block[159:128]);
      write_single_word(addr + 4*8, block[127:96]);
      write_single_word(addr + 4*9, block[95:64]);
      write_single_word(addr + 4*10, block[63:32]);
      write_single_word(addr + 4*11, block[31:0]);
    end
  endtask

  task automatic read_block(input logic [31:0] addr);
    begin
      read_single_word(addr + 4*0); reg_read_data[383:352] = hrdata_o_tb;
      read_single_word(addr + 4*1); reg_read_data[351:320] = hrdata_o_tb;
      read_single_word(addr + 4*2); reg_read_data[319:288] = hrdata_o_tb;
      read_single_word(addr + 4*3); reg_read_data[287:256] = hrdata_o_tb;
      read_single_word(addr + 4*4); reg_read_data[255:224] = hrdata_o_tb;
      read_single_word(addr + 4*5); reg_read_data[223:192] = hrdata_o_tb;
      read_single_word(addr + 4*6); reg_read_data[191:160] = hrdata_o_tb;
      read_single_word(addr + 4*7); reg_read_data[159:128] = hrdata_o_tb;
      read_single_word(addr + 4*8); reg_read_data[127:96] = hrdata_o_tb;
      read_single_word(addr + 4*9); reg_read_data[95:64] = hrdata_o_tb;
      read_single_word(addr + 4*10); reg_read_data[63:32] = hrdata_o_tb;
      read_single_word(addr + 4*11); reg_read_data[31:0] = hrdata_o_tb;
    end
  endtask

  task automatic wait_ready;
    begin
      read_single_word(`ECC_REG_ECC_STATUS);
      while ((hrdata_o_tb & `ECC_REG_ECC_STATUS_READY_MASK) == 0) begin
        read_single_word(`ECC_REG_ECC_STATUS);
      end
    end
  endtask

  task automatic wait_busy;
    begin
      read_single_word(`ECC_REG_ECC_STATUS);
      while ((hrdata_o_tb & `ECC_REG_ECC_STATUS_READY_MASK) != 0) begin
        read_single_word(`ECC_REG_ECC_STATUS);
      end
    end
  endtask

  task automatic wait_kv_privkey_valid;
    begin
      read_single_word(`ECC_REG_ECC_KV_RD_PKEY_STATUS);
      while ((hrdata_o_tb & `ECC_REG_ECC_KV_RD_PKEY_STATUS_VALID_MASK) == 0) begin
        read_single_word(`ECC_REG_ECC_KV_RD_PKEY_STATUS);
      end
    end
  endtask

  task automatic run_test;
    operand_t sign_r;
    operand_t sign_s;
    logic [31:0] tamper_ctrl;
    begin
      wait_ready();
      write_block(`ECC_REG_ECC_MSG_0, MSG);
      write_block(`ECC_REG_ECC_IV_0, IV);

      write_single_word(
          `ECC_REG_ECC_KV_RD_PKEY_CTRL,
          `ECC_REG_ECC_KV_RD_PKEY_CTRL_READ_EN_MASK |
              (32'd1 << `ECC_REG_ECC_KV_RD_PKEY_CTRL_READ_ENTRY_LOW)
      );
      wait_kv_privkey_valid();

      write_single_word(`ECC_REG_ECC_CTRL, ECC_CMD_SIGNING);
      wait_busy();

      #(50 * CLK_PERIOD);
      tamper_ctrl = `ECC_REG_ECC_KV_RD_PKEY_CTRL_READ_EN_MASK |
                    (32'd0 << `ECC_REG_ECC_KV_RD_PKEY_CTRL_READ_ENTRY_LOW);
      write_single_word(`ECC_REG_ECC_KV_RD_PKEY_CTRL, tamper_ctrl);

      wait_ready();

      read_block(`ECC_REG_ECC_SIGN_R_0);
      sign_r = reg_read_data;
      read_block(`ECC_REG_ECC_SIGN_S_0);
      sign_s = reg_read_data;

      if ((sign_r !== SIGN_R) || (sign_s !== SIGN_S)) begin
        $display("Observed sign_r=0x%96x", sign_r);
        $display("Observed sign_s=0x%96x", sign_s);
        $fatal(1, "KV control tamper changed ECC signing result");
      end

      $display("ECC KV control lock test passed");
      $finish;
    end
  endtask

  initial begin
    $display("Start hwe_kv_ctrl_lock_ecc_tb");
    init_sim();
    reset_dut();
    run_test();
  end

endmodule
EOF

rm -rf "${BUILD_DIR}"
mkdir -p "${BUILD_DIR}"
cd "${BUILD_DIR}" || exit 2

status=0

verilator --binary --timing \
  -Wno-WIDTH -Wno-UNOPTFLAT -Wno-LITENDIAN -Wno-CMPCONST -Wno-MULTIDRIVEN -Wno-UNPACKED -Wno-LATCH \
  -f /home/caliptra-rtl/src/ecc/config/ecc_top_tb.vf \
  "${TB_FILE}" \
  --top-module "${TB_NAME}"
status=$?

if [ "${status}" -eq 0 ]; then
  "./obj_dir/V${TB_NAME}"
  status=$?
fi

echo "HWE_BENCH_RESULTS_START"
if [ "${status}" -eq 0 ]; then
  echo "TEST: kv_ctrl_lock_ecc ... PASS"
else
  echo "TEST: kv_ctrl_lock_ecc ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "${status}"

