    axi_arsize = 3'b010;
    axi_arprot = '0;
    axi_rready = 1'b1;

    ahb_hrdata = 64'h0123_4567_89ab_cdef;
    ahb_hready = 1'b1;
    ahb_hresp = 1'b0;

    repeat (2) @(negedge clk);
    rst_l = 1'b1;
    repeat (2) @(posedge clk);

    @(negedge clk);
    axi_arvalid = 1'b1;
    axi_araddr = FIRST_ADDR;
    #1;
    if (ahb_htrans !== 2'b10 || ahb_haddr !== FIRST_ADDR) begin
      $display("First read launch mismatch: htrans=%b haddr=%08x", ahb_htrans, ahb_haddr);
      $fatal(1, "first read launch mismatch");
    end

    @(posedge clk);
    @(negedge clk);
    axi_araddr = SECOND_ADDR;
    ahb_hready = 1'b0;
    #1;
    if (ahb_htrans !== 2'b10 || ahb_haddr !== SECOND_ADDR) begin
      $display("Second read launch mismatch: htrans=%b haddr=%08x", ahb_htrans, ahb_haddr);
      $fatal(1, "second read launch mismatch");
    end

    @(posedge clk);
    #1;
    if (ahb_htrans !== 2'b10) begin
      $display("Stalled stream read changed HTRANS: htrans=%b haddr=%08x", ahb_htrans, ahb_haddr);
      $fatal(1, "stalled stream read changed HTRANS");
    end
    if (ahb_haddr !== SECOND_ADDR) begin
      $display("Stalled stream read lost address bits: htrans=%b haddr=%08x expected=%08x", ahb_htrans, ahb_haddr, SECOND_ADDR);
      $fatal(1, "stalled stream read lost address bits");
    end

    $display("axi4_to_ahb stream read stall repro passed");
    $finish;
  end
endmodule
