tb_script:
#!/bin/bash
set -uo pipefail

cd /home/caliptra-rtl

workdir="/home/caliptra-rtl/.hwe_pr747_ahb_slv_sif"
tb_file="${workdir}/ahb_slv_sif_error_tb.sv"
obj_dir="${workdir}/obj_dir"
compile_log="${workdir}/compile.log"
run_log="${workdir}/run.log"
test_name="ahb_slv_sif_clears_dv_after_error"

rm -rf "${workdir}"
mkdir -p "${workdir}"

cat > "${tb_file}" <<'SV'
module ahb_slv_sif_error_tb;
  timeunit 1ns;
  timeprecision 1ps;

  import ahb_defines_pkg::*;

  localparam int AHB_DATA_WIDTH = 32;
  localparam int CLIENT_DATA_WIDTH = 32;
  localparam int AHB_ADDR_WIDTH = 32;
  localparam int CLIENT_ADDR_WIDTH = 32;

  logic hclk = 0;
  logic hreset_n = 0;
  logic [AHB_ADDR_WIDTH-1:0] haddr_i = '0;
  logic [AHB_DATA_WIDTH-1:0] hwdata_i = '0;
  logic hsel_i = 0;
  logic hwrite_i = 0;
  logic hready_i = 0;
  logic [1:0] htrans_i = 2'b00;
  logic [2:0] hsize_i = 3'b010;

  logic hresp_o;
  logic hreadyout_o;
  logic [AHB_DATA_WIDTH-1:0] hrdata_o;

  logic dv;
  logic hld = 0;
  logic err = 0;
  logic write;
  logic [CLIENT_DATA_WIDTH-1:0] wdata;
  logic [CLIENT_ADDR_WIDTH-1:0] addr;
  logic [CLIENT_DATA_WIDTH-1:0] rdata = '0;

  ahb_slv_sif #(
    .AHB_DATA_WIDTH(AHB_DATA_WIDTH),
    .CLIENT_DATA_WIDTH(CLIENT_DATA_WIDTH),
    .AHB_ADDR_WIDTH(AHB_ADDR_WIDTH),
    .CLIENT_ADDR_WIDTH(CLIENT_ADDR_WIDTH)
  ) dut (
    .hclk,
    .hreset_n,
    .haddr_i,
    .hwdata_i,
    .hsel_i,
    .hwrite_i,
    .hready_i,
    .htrans_i,
    .hsize_i,
    .hresp_o,
    .hreadyout_o,
    .hrdata_o,
    .dv,
    .hld,
    .err,
    .write,
    .wdata,
    .addr,
    .rdata
  );

  always #1 hclk = ~hclk;

  task automatic step(
    input logic next_hready_i,
    input logic next_hsel_i,
    input logic [1:0] next_htrans_i,
    input logic next_hwrite_i,
    input logic [AHB_ADDR_WIDTH-1:0] next_haddr_i,
    input logic [AHB_DATA_WIDTH-1:0] next_hwdata_i,
    input logic next_hld,
    input logic next_err
  );
    begin
      @(negedge hclk);
      hready_i = next_hready_i;
      hsel_i = next_hsel_i;
      htrans_i = next_htrans_i;
      hwrite_i = next_hwrite_i;
      haddr_i = next_haddr_i;
      hwdata_i = next_hwdata_i;
      hld = next_hld;
      err = next_err;
      @(posedge hclk);
      @(negedge hclk);
    end
  endtask

  task automatic check_or_die(
    input bit cond,
    input string msg
  );
    begin
      if (!cond) begin
        $display("TB_ERROR: %s", msg);
        $fatal(1);
      end
    end
  endtask

  task automatic show_state(input string tag);
    begin
      $display(
        "TB_STATE %s hready_i=%0b hsel_i=%0b htrans_i=%0h hld=%0b err=%0b dv=%0b hreadyout_o=%0b hresp_o=%0b err_f=%0b",
        tag, hready_i, hsel_i, htrans_i, hld, err, dv, hreadyout_o, hresp_o, dut.err_f
      );
    end
  endtask

  initial begin
    repeat (2) @(negedge hclk);
    hreset_n = 1'b1;

    step(1'b1, 1'b1, 2'b10, 1'b1, 32'h0000_0040, 32'hCAFE_BABE, 1'b0, 1'b0);
    show_state("request");
    check_or_die(dv == 1'b1, "request was not presented to the component");
    check_or_die(write == 1'b1, "write qualifier was not latched");
    check_or_die(addr == 32'h0000_0040, "address was not latched");
    check_or_die(hreadyout_o == 1'b1, "ready should stay high when the component accepts the request");

    step(1'b0, 1'b0, 2'b00, 1'b0, '0, '0, 1'b1, 1'b0);
    show_state("hold");
    check_or_die(dv == 1'b1, "dv should remain asserted while the component holds the request");
    check_or_die(hreadyout_o == 1'b0, "hold should back-pressure the AHB bus");
    check_or_die(hresp_o == H_OKAY, "hold cycle should still report OKAY");

    step(1'b0, 1'b0, 2'b00, 1'b0, '0, '0, 1'b0, 1'b1);
    show_state("error");
    check_or_die(hresp_o == H_ERROR, "error response should be visible on the AHB side");
    check_or_die(dv == 1'b0, "dv should clear as soon as the component reports an error");

    step(1'b0, 1'b0, 2'b00, 1'b0, '0, '0, 1'b0, 1'b0);
    show_state("recovery");
    check_or_die(hreadyout_o == 1'b1, "second error cycle should release the bus");
    check_or_die(dv == 1'b0, "dv must stay low after the error response has completed");

    $display("TB_PASS");
    $finish;
  end
endmodule
SV

compile_rc=0
run_rc=0
result="FAIL"

verilator --binary --assert --timing -sv \
  -Wno-fatal -Wno-DECLFILENAME -Wno-UNUSEDSIGNAL -Wno-WIDTH \
  --top-module ahb_slv_sif_error_tb \
  --Mdir "${obj_dir}" \
  src/libs/rtl/ahb_defines_pkg.sv \
  src/libs/rtl/ahb_slv_sif.sv \
  "${tb_file}" \
  > "${compile_log}" 2>&1 || compile_rc=$?

if [[ "${compile_rc}" -eq 0 ]]; then
  "${obj_dir}/Vahb_slv_sif_error_tb" > "${run_log}" 2>&1 || run_rc=$?
else
  run_rc=1
fi

echo "HWE_BENCH_RESULTS_START"
if [[ "${compile_rc}" -eq 0 && "${run_rc}" -eq 0 ]]; then
  result="PASS"
else
  result="FAIL"
fi
echo "TEST: ${test_name} ... ${result}"
echo "HWE_BENCH_RESULTS_END"

if [[ "${compile_rc}" -ne 0 ]]; then
  tail -n 60 "${compile_log}" >&2 || true
  exit "${compile_rc}"
fi

if [[ "${run_rc}" -ne 0 ]]; then
  tail -n 60 "${run_log}" >&2 || true
  exit "${run_rc}"
fi

exit 0

#!/bin/bash
set -euo pipefail

cd /home/caliptra-rtl

workdir=/home/caliptra-rtl/.hwe_axi_sub_arb
rm -rf "$workdir"
mkdir -p "$workdir"

cat > "$workdir/axi_sub_arb_issue_tb.sv" <<'SVEOF'
`timescale 1ns/1ps

module axi_sub_arb_issue_tb;
  import axi_pkg::*;

  localparam int AW = 32;
  localparam int DW = 32;
  localparam int UW = 8;
  localparam int IW = 2;
  localparam logic [AW-1:0] READ_ADDR  = 32'h0000_0040;
  localparam logic [AW-1:0] WRITE_ADDR = 32'h0000_0020;

  logic clk;
  logic rst_n;

  logic          r_dv;
  logic [AW-1:0] r_addr;
  logic [UW-1:0] r_user;
  logic [IW-1:0] r_id;
  logic [2:0]    r_size;
  logic          r_last;
  logic          r_hld;
  logic          r_err;
  logic [DW-1:0] r_rdata;

  logic          w_dv;
  logic [AW-1:0] w_addr;
  logic [UW-1:0] w_user;
  logic [IW-1:0] w_id;
  logic [DW-1:0] w_wdata;
  logic [DW/8-1:0] w_wstrb;
  logic [2:0]    w_size;
  logic          w_last;
  logic          w_hld;
  logic          w_err;

  logic          dv;
  logic [AW-1:0] addr;
  logic          write;
  logic [UW-1:0] user;
  logic [IW-1:0] id;
  logic [DW-1:0] wdata;
  logic [DW/8-1:0] wstrb;
  logic [2:0]    size;
  logic          last;
  logic          hld;
  logic          rd_err;
  logic          wr_err;
  logic [DW-1:0] rdata;

  bit failed;

  axi_sub_arb #(
    .AW(AW),
    .DW(DW),
    .UW(UW),
    .IW(IW),
    .C_LAT(0)
  ) dut (
    .clk(clk),
    .rst_n(rst_n),
    .r_dv(r_dv),
    .r_addr(r_addr),
    .r_user(r_user),
    .r_id(r_id),
    .r_size(r_size),
    .r_last(r_last),
    .r_hld(r_hld),
    .r_err(r_err),
    .r_rdata(r_rdata),
    .w_dv(w_dv),
    .w_addr(w_addr),
    .w_user(w_user),
    .w_id(w_id),
    .w_wdata(w_wdata),
    .w_wstrb(w_wstrb),
    .w_size(w_size),
    .w_last(w_last),
    .w_hld(w_hld),
    .w_err(w_err),
    .dv(dv),
    .addr(addr),
    .write(write),
    .user(user),
    .id(id),
    .wdata(wdata),
    .wstrb(wstrb),
    .size(size),
    .last(last),
    .hld(hld),
    .rd_err(rd_err),
    .wr_err(wr_err),
    .rdata(rdata)
  );

  always #5 clk = ~clk;

  task automatic fail_case;
    begin
      failed = 1'b1;
    end
  endtask

  task automatic drive_cycle(
    input logic        i_r_dv,
    input logic [2:0]  i_r_size,
    input logic        i_r_last,
    input logic        i_w_dv,
    input logic [2:0]  i_w_size,
    input logic        i_w_last,
    input logic        i_hld
  );
    begin
      r_dv = i_r_dv;
      r_size = i_r_size;
      r_last = i_r_last;
      w_dv = i_w_dv;
      w_size = i_w_size;
      w_last = i_w_last;
      hld = i_hld;
      #1;
    end
  endtask

  initial begin
    clk = 1'b0;
    rst_n = 1'b0;
    failed = 1'b0;

    r_dv = 1'b0;
    r_addr = READ_ADDR;
    r_user = UW'(8'h11);
    r_id = IW'(2'h1);
    r_size = 3'd2;
    r_last = 1'b0;

    w_dv = 1'b0;
    w_addr = WRITE_ADDR;
    w_user = UW'(8'h22);
    w_id = IW'(2'h2);
    w_wdata = 32'hDEAD_BEEF;
    w_wstrb = '1;
    w_size = 3'd2;
    w_last = 1'b0;

    hld = 1'b0;
    rd_err = 1'b0;
    wr_err = 1'b0;
    rdata = 32'hC0DE_0040;

    repeat (2) @(posedge clk);
    rst_n = 1'b1;

    // Cycle 0: a single-beat read has already won arbitration, but the downstream
    // component is holding the transfer off. The arbiter comment explicitly says the
    // current winner must keep priority when granted during a hold.
    @(negedge clk);
    drive_cycle(1'b1, 3'd2, 1'b1, 1'b0, 3'd0, 1'b0, 1'b1);
    if (!(dv && !write && addr == READ_ADDR && r_hld && w_hld)) begin
      $display("TB_ERROR: stalled read setup cycle did not select the read beat");
      fail_case();
    end
    @(posedge clk);

    // Cycle 1: the same read beat is still stalled and pending.
    @(negedge clk);
    drive_cycle(1'b1, 3'd2, 1'b1, 1'b0, 3'd0, 1'b0, 1'b1);
    if (!(dv && !write && addr == READ_ADDR && r_hld && w_hld)) begin
      $display("TB_ERROR: repeated stalled read cycle did not preserve the read beat");
      fail_case();
    end
    @(posedge clk);

    // Cycle 2: the hold is released exactly when a single-beat write also becomes ready.
    // Correct behavior is to finish the already-granted read first, then let the write go.
    @(negedge clk);
    drive_cycle(1'b1, 3'd2, 1'b1, 1'b1, 3'd2, 1'b1, 1'b0);
    if (!(dv && !write && addr == READ_ADDR && !r_hld && w_hld)) begin
      $display(
        "TB_ERROR: arbiter switched away from the stalled read when the write arrived; write=%0d addr=0x%08x r_hld=%0d w_hld=%0d",
        write,
        addr,
        r_hld,
        w_hld
      );
      fail_case();
    end
    @(posedge clk);

    // Cycle 3: once the read completes, the pending write should be selected.
    @(negedge clk);
    drive_cycle(1'b0, 3'd0, 1'b0, 1'b1, 3'd2, 1'b1, 1'b0);
    if (!(dv && write && addr == WRITE_ADDR && r_hld && !w_hld && wdata == 32'hDEAD_BEEF)) begin
      $display(
        "TB_ERROR: write beat was not serviced after the stalled read completed; write=%0d addr=0x%08x r_hld=%0d w_hld=%0d data=0x%08x",
        write,
        addr,
        r_hld,
        w_hld,
        wdata
      );
      fail_case();
    end
    @(posedge clk);

    if (failed) begin
      $fatal(1, "axi_sub_arb violated winner persistence across a downstream hold");
    end

    $display("TB_INFO: stalled-read arbitration behavior is correct");
    $finish;
  end
endmodule
SVEOF

compile_cmd=(
  verilator
  --binary
  --sv
  --timing
  --top-module axi_sub_arb_issue_tb
  --Mdir "$workdir/obj_dir"
  -Wno-fatal
  -Wno-DECLFILENAME
  -Wno-TIMESCALEMOD
  -Wno-LATCH
  -Wno-UNOPTFLAT
  -Wno-WIDTH
  -Wno-UNSIGNED
  -Wno-UNUSEDSIGNAL
  -Wno-UNUSEDPARAM
  -Wno-IMPORTSTAR
  -I/home/caliptra-rtl/src/libs/rtl
  -I/home/caliptra-rtl/src/caliptra_prim/rtl
  /home/caliptra-rtl/src/axi/rtl/axi_pkg.sv
  /home/caliptra-rtl/src/axi/rtl/axi_sub_arb.sv
  "$workdir/axi_sub_arb_issue_tb.sv"
)

echo "HWE_BENCH_RESULTS_START"
if ! "${compile_cmd[@]}"; then
  echo "TEST: stalled_read_winner_persistence ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  exit 1
fi

if "$workdir/obj_dir/Vaxi_sub_arb_issue_tb"; then
  echo "TEST: stalled_read_winner_persistence ... PASS"
  echo "HWE_BENCH_RESULTS_END"
  exit 0
else
  status=$?
  echo "TEST: stalled_read_winner_persistence ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  exit "$status"
fi

