#!/bin/bash
set -euo pipefail

cd /home/caliptra-rtl

TEST_NAME="aes_manual_gcm_tag"
WORK_DIR="/home/caliptra-rtl/.hwebench/${TEST_NAME}"
TB_FILE="${WORK_DIR}/${TEST_NAME}_tb.sv"
FILELIST="${WORK_DIR}/${TEST_NAME}.f"
OBJ_DIR="${WORK_DIR}/obj_dir"
BUILD_LOG="${WORK_DIR}/${TEST_NAME}.build.log"
RUN_LOG="${WORK_DIR}/${TEST_NAME}.run.log"
SIM_EXE="${OBJ_DIR}/V${TEST_NAME}_tb"

rm -rf "${WORK_DIR}"
mkdir -p "${WORK_DIR}"

cat > "${TB_FILE}" <<'EOF'
`timescale 1ns/1ps

module aes_manual_gcm_tag_tb;
  import aes_pkg::*;
  import aes_reg_pkg::*;

  logic clk_i = 1'b0;
  logic rst_ni = 1'b0;

  logic ctrl_qe_i = 1'b0;
  logic ctrl_we_o;
  logic ctrl_phase_i = 1'b0;
  logic ctrl_err_storage_i = 1'b0;
  aes_op_e op_i = AES_ENC;
  aes_mode_e mode_i = AES_GCM;
  ciph_op_e cipher_op_i = CIPH_FWD;
  logic sideload_i = 1'b0;
  prs_rate_e prng_reseed_rate_i = PER_1;
  logic manual_operation_i = 1'b1;
  logic key_touch_forces_reseed_i = 1'b0;
  logic ctrl_gcm_qe_i = 1'b0;
  logic ctrl_gcm_we_o;
  gcm_phase_e gcm_phase_i = GCM_TAG;
  logic start_i = 1'b0;
  logic key_iv_data_in_clear_i = 1'b0;
  logic data_out_clear_i = 1'b0;
  logic prng_reseed_i = 1'b0;
  logic mux_sel_err_i = 1'b0;
  logic sp_enc_err_i = 1'b0;
  lc_ctrl_pkg::lc_tx_t lc_escalate_en_i = lc_ctrl_pkg::Off;
  logic alert_fatal_i = 1'b0;
  logic alert_o;

  logic key_sideload_valid_i = 1'b0;
  logic [NumSharesKey-1:0][NumRegsKey-1:0] key_init_qe_i = '0;
  logic [NumRegsIv-1:0] iv_qe_i = '0;
  logic [NumRegsData-1:0] data_in_qe_i = '0;
  logic [NumRegsData-1:0] data_out_re_i = '0;
  logic data_in_we_o;
  data_out_sel_e data_out_sel_o;
  logic data_out_we_o;

  dip_sel_e data_in_prev_sel_o;
  logic data_in_prev_we_o;

  si_sel_e state_in_sel_o;
  add_si_sel_e add_state_in_sel_o;
  add_so_sel_e add_state_out_sel_o;

  logic ctr_inc32_o;
  logic ctr_incr_o;
  logic ctr_ready_i = 1'b1;
  logic [NumSlicesCtr-1:0] ctr_we_i = '0;

  logic cipher_in_valid_o;
  logic cipher_in_ready_i = 1'b1;
  logic cipher_out_valid_i = 1'b0;
  logic cipher_out_ready_o;
  logic cipher_crypt_o;
  logic cipher_crypt_i = 1'b0;
  logic cipher_dec_key_gen_o;
  logic cipher_dec_key_gen_i = 1'b0;
  logic cipher_prng_reseed_o;
  logic cipher_prng_reseed_i = 1'b0;
  logic cipher_key_clear_o;
  logic cipher_key_clear_i = 1'b0;
  logic cipher_data_out_clear_o;
  logic cipher_data_out_clear_i = 1'b0;

  logic ghash_in_valid_o;
  logic ghash_in_ready_i = 1'b1;
  logic ghash_out_valid_i = 1'b0;
  logic ghash_out_ready_o;
  logic ghash_load_hash_subkey_o;

  key_init_sel_e key_init_sel_o;
  logic [NumSharesKey-1:0][NumRegsKey-1:0] key_init_we_o;

  iv_sel_e iv_sel_o;
  logic [NumSlicesCtr-1:0] iv_we_o;

  logic prng_update_o;
  logic prng_reseed_req_o;
  logic prng_reseed_ack_i = 1'b0;

  logic start_we_o;
  logic key_iv_data_in_clear_we_o;
  logic data_out_clear_we_o;
  logic prng_reseed_o;
  logic prng_reseed_we_o;

  logic idle_o;
  logic idle_we_o;
  logic stall_o;
  logic stall_we_o;
  logic output_lost_i = 1'b0;
  logic output_lost_o;
  logic output_lost_we_o;
  logic output_valid_o;
  logic output_valid_we_o;
  logic input_ready_o;
  logic input_ready_we_o;

  always #5 clk_i = ~clk_i;

  aes_control_fsm #(
    .AESGCMEnable(1'b1),
    .SecMasking(1'b0)
  ) dut (
    .clk_i(clk_i),
    .rst_ni(rst_ni),
    .ctrl_qe_i(ctrl_qe_i),
    .ctrl_we_o(ctrl_we_o),
    .ctrl_phase_i(ctrl_phase_i),
    .ctrl_err_storage_i(ctrl_err_storage_i),
    .op_i(op_i),
    .mode_i(mode_i),
    .cipher_op_i(cipher_op_i),
    .sideload_i(sideload_i),
    .prng_reseed_rate_i(prng_reseed_rate_i),
    .manual_operation_i(manual_operation_i),
    .key_touch_forces_reseed_i(key_touch_forces_reseed_i),
    .ctrl_gcm_qe_i(ctrl_gcm_qe_i),
    .ctrl_gcm_we_o(ctrl_gcm_we_o),
    .gcm_phase_i(gcm_phase_i),
    .start_i(start_i),
    .key_iv_data_in_clear_i(key_iv_data_in_clear_i),
    .data_out_clear_i(data_out_clear_i),
    .prng_reseed_i(prng_reseed_i),
    .mux_sel_err_i(mux_sel_err_i),
    .sp_enc_err_i(sp_enc_err_i),
    .lc_escalate_en_i(lc_escalate_en_i),
    .alert_fatal_i(alert_fatal_i),
    .alert_o(alert_o),
    .key_sideload_valid_i(key_sideload_valid_i),
    .key_init_qe_i(key_init_qe_i),
    .iv_qe_i(iv_qe_i),
    .data_in_qe_i(data_in_qe_i),
    .data_out_re_i(data_out_re_i),
    .data_in_we_o(data_in_we_o),
    .data_out_sel_o(data_out_sel_o),
    .data_out_we_o(data_out_we_o),
    .data_in_prev_sel_o(data_in_prev_sel_o),
    .data_in_prev_we_o(data_in_prev_we_o),
    .state_in_sel_o(state_in_sel_o),
    .add_state_in_sel_o(add_state_in_sel_o),
    .add_state_out_sel_o(add_state_out_sel_o),
    .ctr_inc32_o(ctr_inc32_o),
    .ctr_incr_o(ctr_incr_o),
    .ctr_ready_i(ctr_ready_i),
    .ctr_we_i(ctr_we_i),
    .cipher_in_valid_o(cipher_in_valid_o),
    .cipher_in_ready_i(cipher_in_ready_i),
    .cipher_out_valid_i(cipher_out_valid_i),
    .cipher_out_ready_o(cipher_out_ready_o),
    .cipher_crypt_o(cipher_crypt_o),
    .cipher_crypt_i(cipher_crypt_i),
    .cipher_dec_key_gen_o(cipher_dec_key_gen_o),
    .cipher_dec_key_gen_i(cipher_dec_key_gen_i),
    .cipher_prng_reseed_o(cipher_prng_reseed_o),
    .cipher_prng_reseed_i(cipher_prng_reseed_i),
    .cipher_key_clear_o(cipher_key_clear_o),
    .cipher_key_clear_i(cipher_key_clear_i),
    .cipher_data_out_clear_o(cipher_data_out_clear_o),
    .cipher_data_out_clear_i(cipher_data_out_clear_i),
    .ghash_in_valid_o(ghash_in_valid_o),
    .ghash_in_ready_i(ghash_in_ready_i),
    .ghash_out_valid_i(ghash_out_valid_i),
    .ghash_out_ready_o(ghash_out_ready_o),
    .ghash_load_hash_subkey_o(ghash_load_hash_subkey_o),
    .key_init_sel_o(key_init_sel_o),
    .key_init_we_o(key_init_we_o),
    .iv_sel_o(iv_sel_o),
    .iv_we_o(iv_we_o),
    .prng_update_o(prng_update_o),
    .prng_reseed_req_o(prng_reseed_req_o),
    .prng_reseed_ack_i(prng_reseed_ack_i),
    .start_we_o(start_we_o),
    .key_iv_data_in_clear_we_o(key_iv_data_in_clear_we_o),
    .data_out_clear_we_o(data_out_clear_we_o),
    .prng_reseed_o(prng_reseed_o),
    .prng_reseed_we_o(prng_reseed_we_o),
    .idle_o(idle_o),
    .idle_we_o(idle_we_o),
    .stall_o(stall_o),
    .stall_we_o(stall_we_o),
    .output_lost_i(output_lost_i),
    .output_lost_o(output_lost_o),
    .output_lost_we_o(output_lost_we_o),
    .output_valid_o(output_valid_o),
    .output_valid_we_o(output_valid_we_o),
    .input_ready_o(input_ready_o),
    .input_ready_we_o(input_ready_we_o)
  );

  task automatic check_or_fail(input bit cond, input string msg);
    if (!cond) begin
      $display("FAIL: %s", msg);
      $fatal(1);
    end
  endtask

  task automatic write_data_word(input int idx);
    begin
      data_in_qe_i = {{(NumRegsData - 1){1'b0}}, 1'b1} << idx;
      @(posedge clk_i);
      @(negedge clk_i);
      data_in_qe_i = '0;
      @(posedge clk_i);
      @(negedge clk_i);
    end
  endtask

  initial begin
    repeat (2) @(negedge clk_i);
    rst_ni = 1'b1;
    repeat (2) @(negedge clk_i);

    write_data_word(0);
    write_data_word(1);
    write_data_word(2);
    write_data_word(3);

    check_or_fail(input_ready_o === 1'b0, "input block did not become full");
    check_or_fail(idle_o === 1'b1, "module left IDLE before manual START");
    check_or_fail(start_we_o === 1'b0, "manual START trigger was consumed before START");
    check_or_fail(data_in_prev_we_o === 1'b0, "data moved into GHASH path before START");
    check_or_fail(ghash_in_valid_o === 1'b0, "GHASH started before manual START");

    repeat (2) begin
      @(negedge clk_i);
      check_or_fail(idle_o === 1'b1, "module stopped being IDLE before manual START");
      check_or_fail(ghash_in_valid_o === 1'b0, "GHASH activity observed before manual START");
    end

    start_i = 1'b1;
    #1;
    check_or_fail(start_we_o === 1'b1, "manual START did not clear the trigger");
    check_or_fail(data_in_prev_we_o === 1'b1, "manual START did not capture the input block");
    @(posedge clk_i);
    @(negedge clk_i);
    start_i = 1'b0;

    begin
      bit saw_ghash_valid;
      saw_ghash_valid = 1'b0;
      repeat (4) begin
        @(negedge clk_i);
        if (ghash_in_valid_o === 1'b1) begin
          saw_ghash_valid = 1'b1;
        end
      end
      check_or_fail(saw_ghash_valid, "manual START did not drive GHASH input valid");
    end

    $display("PASS: GCM TAG waits for START in manual mode");
    $finish;
  end
endmodule
EOF

cat > "${FILELIST}" <<'EOF'
+incdir+/home/caliptra-rtl/src/libs/rtl
+incdir+/home/caliptra-rtl/src/caliptra_prim/rtl
+incdir+/home/caliptra-rtl/src/lc_ctrl/rtl
+incdir+/home/caliptra-rtl/src/caliptra_prim_generic/rtl
+incdir+/home/caliptra-rtl/src/aes/rtl
/home/caliptra-rtl/src/caliptra_prim/rtl/caliptra_prim_util_pkg.sv
/home/caliptra-rtl/src/caliptra_prim/rtl/caliptra_prim_alert_pkg.sv
/home/caliptra-rtl/src/caliptra_prim/rtl/caliptra_prim_subreg_pkg.sv
/home/caliptra-rtl/src/caliptra_prim/rtl/caliptra_prim_mubi_pkg.sv
/home/caliptra-rtl/src/caliptra_prim/rtl/caliptra_prim_cipher_pkg.sv
/home/caliptra-rtl/src/caliptra_prim/rtl/caliptra_prim_pkg.sv
/home/caliptra-rtl/src/caliptra_prim/rtl/caliptra_prim_sparse_fsm_pkg.sv
/home/caliptra-rtl/src/caliptra_prim/rtl/keymgr_pkg.sv
/home/caliptra-rtl/src/lc_ctrl/rtl/lc_ctrl_reg_pkg.sv
/home/caliptra-rtl/src/lc_ctrl/rtl/lc_ctrl_state_pkg.sv
/home/caliptra-rtl/src/lc_ctrl/rtl/lc_ctrl_pkg.sv
/home/caliptra-rtl/src/aes/rtl/aes_reg_pkg.sv
/home/caliptra-rtl/src/aes/rtl/aes_pkg.sv
/home/caliptra-rtl/src/caliptra_prim_generic/rtl/caliptra_prim_generic_flop.sv
/home/caliptra-rtl/src/caliptra_prim/rtl/caliptra_prim_flop.sv
/home/caliptra-rtl/src/caliptra_prim/rtl/caliptra_prim_sparse_fsm_flop.sv
/home/caliptra-rtl/src/aes/rtl/aes_reg_status.sv
/home/caliptra-rtl/src/aes/rtl/aes_control_fsm.sv
EOF

rm -rf "${OBJ_DIR}" "${BUILD_LOG}" "${RUN_LOG}"

set +e
timeout 1800s verilator \
  --binary \
  --timing \
  --Wno-fatal \
  -Wno-WIDTH \
  -Wno-UNOPTFLAT \
  -Wno-LITENDIAN \
  -Wno-CMPCONST \
  -Wno-MULTIDRIVEN \
  -Wno-UNPACKED \
  -Wno-TIMESCALEMOD \
  -Wno-LATCH \
  -F "${FILELIST}" \
  "${TB_FILE}" \
  --top-module "${TEST_NAME}_tb" \
  --Mdir "${OBJ_DIR}" \
  2>&1 | tee "${BUILD_LOG}"
build_status=${PIPESTATUS[0]}

run_status=1
if [[ ${build_status} -eq 0 ]]; then
  timeout 1800s "${SIM_EXE}" 2>&1 | tee "${RUN_LOG}"
  run_status=${PIPESTATUS[0]}
fi
set -e

test_status="FAIL"
exit_code=1
if [[ ${build_status} -eq 0 && ${run_status} -eq 0 ]]; then
  test_status="PASS"
  exit_code=0
fi

echo "HWE_BENCH_RESULTS_START"
echo "TEST: aes_manual_gcm_tag ... ${test_status}"
echo "HWE_BENCH_RESULTS_END"

exit "${exit_code}"

