#!/bin/bash
set -euo pipefail

cd /home/caliptra-rtl

test_name="ecc_add_sub_mod_alter_ready_alignment"
workdir="/home/caliptra-rtl/.hwe_pr594_ecc_ready"
tb_file="${workdir}/ecc_add_sub_mod_alter_ready_tb.sv"
build_log="${workdir}/verilator_build.log"
run_log="${workdir}/verilator_run.log"
status=0

rm -rf "${workdir}"
mkdir -p "${workdir}"

cat > "${tb_file}" <<'SV'
`timescale 1ns/1ps

module ecc_add_sub_mod_alter_ready_tb;
    localparam int REG_SIZE = 8;

    logic clk;
    logic reset_n;
    logic zeroize;
    logic add_en_i;
    logic sub_i;
    logic [REG_SIZE-1:0] opa_i;
    logic [REG_SIZE-1:0] opb_i;
    logic [REG_SIZE-1:0] prime_i;
    logic [REG_SIZE-1:0] res_o;
    logic ready_o;

    ecc_add_sub_mod_alter #(
        .REG_SIZE(REG_SIZE)
    ) dut (
        .clk(clk),
        .reset_n(reset_n),
        .zeroize(zeroize),
        .add_en_i(add_en_i),
        .sub_i(sub_i),
        .opa_i(opa_i),
        .opb_i(opb_i),
        .prime_i(prime_i),
        .res_o(res_o),
        .ready_o(ready_o)
    );

    always #5 clk = ~clk;

    task automatic expect_ready_result(input logic [REG_SIZE-1:0] expected);
    begin
        @(posedge clk);
        #1;

        if (!ready_o) begin
            $display("ERROR: ready_o was low when the result should be valid");
            $fatal(1);
        end

        if (res_o !== expected) begin
            $display("ERROR: expected result 0x%0h but got 0x%0h", expected, res_o);
            $fatal(1);
        end

        @(posedge clk);
        #1;

        if (ready_o) begin
            $display("ERROR: ready_o remained asserted for more than one cycle");
            $fatal(1);
        end
    end
    endtask

    initial begin
        clk = 1'b0;
        reset_n = 1'b0;
        zeroize = 1'b0;
        add_en_i = 1'b0;
        sub_i = 1'b0;
        opa_i = '0;
        opb_i = '0;
        prime_i = '0;

        repeat (2) @(posedge clk);
        reset_n = 1'b1;

        @(negedge clk);
        // Launch a single modular-add transaction: (3 + 4) mod 13 = 7.
        add_en_i = 1'b1;
        sub_i = 1'b0;
        opa_i = 8'd3;
        opb_i = 8'd4;
        prime_i = 8'd13;

        @(posedge clk);
        #1;

        add_en_i = 1'b0;

        // Disturb all inputs before ready_o. A correct design must still return 7.
        sub_i = 1'b1;
        opa_i = 8'd9;
        opb_i = 8'd8;
        prime_i = 8'd19;

        expect_ready_result(8'd7);

        $display("TB PASS");
        $finish;
    end
endmodule
SV

if ! verilator \
    --binary \
    --timing \
    -Wno-fatal \
    -Wno-TIMESCALEMOD \
    -Wno-WIDTHEXPAND \
    --top-module ecc_add_sub_mod_alter_ready_tb \
    --Mdir "${workdir}/obj_dir" \
    src/ecc/rtl/ecc_adder.sv \
    src/ecc/rtl/ecc_add_sub_mod_alter.sv \
    "${tb_file}" \
    >"${build_log}" 2>&1; then
    status=1
fi

if [[ ${status} -eq 0 ]]; then
    if ! "${workdir}/obj_dir/Vecc_add_sub_mod_alter_ready_tb" >"${run_log}" 2>&1; then
        status=1
    fi
fi

echo "HWE_BENCH_RESULTS_START"
if [[ ${status} -eq 0 ]]; then
    echo "TEST: ${test_name} ... PASS"
else
    echo "TEST: ${test_name} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

if [[ ${status} -ne 0 ]]; then
    if [[ -f "${build_log}" ]]; then
        echo "[build log tail]"
        tail -n 40 "${build_log}"
    fi
    if [[ -f "${run_log}" ]]; then
        echo "[run log tail]"
        tail -n 40 "${run_log}"
    fi
    exit 1
fi

