#!/bin/bash
set -euo pipefail

cd /home/caliptra-rtl

export CALIPTRA_ROOT=/home/caliptra-rtl
export CALIPTRA_HOME=/home/caliptra-rtl

scratch_dir="/home/caliptra-rtl/.hwe_pr506"
tb_top="entropy_src_fw_ov_overflow_tb"
tb_sv="${scratch_dir}/${tb_top}.sv"
tb_cpp="${scratch_dir}/test_${tb_top}.cpp"
tb_vf="${scratch_dir}/${tb_top}.vf"
obj_dir="${scratch_dir}/obj_dir"

rm -rf "${scratch_dir}"
mkdir -p "${scratch_dir}"
mkdir -p "${obj_dir}"

cat > "${tb_sv}" <<'TBEOF'
module entropy_src_fw_ov_overflow_tb
  import entropy_src_pkg::*;
  import entropy_src_reg_pkg::*;
(
`ifdef VERILATOR
  input bit clk_tb
`endif
  );

  parameter CLK_HALF_PERIOD = 2;
  parameter ADDR_CONF                    = 32'h24;
  parameter ADDR_MODULE_ENABLE           = 32'h20;
  parameter ADDR_FW_OV_CONTROL           = 32'hb0;
  parameter ADDR_FW_OV_RD_FIFO_OVERFLOW  = 32'hbc;
  parameter ADDR_FW_OV_RD_DATA           = 32'hc0;
  parameter ADDR_OBSERVE_FIFO_DEPTH      = 32'hcc;

  parameter AHB_HTRANS_IDLE   = 0;
  parameter AHB_HTRANS_NONSEQ = 2;

  parameter AHB_ADDR_WIDTH = 32;
  parameter AHB_DATA_WIDTH = 32;

  logic generate_rng;

`ifndef VERILATOR
  reg clk_tb;
`endif
  reg reset_n_tb;

  reg [AHB_ADDR_WIDTH-1:0] haddr_i_tb;
  reg [AHB_DATA_WIDTH-1:0] hwdata_i_tb;
  reg hsel_i_tb;
  reg hwrite_i_tb;
  reg hready_i_tb;
  reg [1:0] htrans_i_tb;
  reg [2:0] hsize_i_tb;

  wire hresp_o_tb;
  wire hreadyout_o_tb;
  logic [AHB_DATA_WIDTH-1:0] hrdata_o_tb;
  reg [31:0] read_data;

  entropy_src_hw_if_req_t entropy_src_hw_if_req;
  entropy_src_hw_if_rsp_t entropy_src_hw_if_rsp;
  entropy_src_rng_req_t entropy_src_rng_req;
  entropy_src_rng_rsp_t entropy_src_rng_rsp;

  entropy_src #(
    .AHBDataWidth(AHB_DATA_WIDTH),
    .AHBAddrWidth(AHB_ADDR_WIDTH)
  ) dut (
    .clk_i       (clk_tb),
    .rst_ni      (reset_n_tb),
    .haddr_i     (haddr_i_tb),
    .hwdata_i    (hwdata_i_tb),
    .hsel_i      (hsel_i_tb),
    .hwrite_i    (hwrite_i_tb),
    .hready_i    (hready_i_tb),
    .htrans_i    (htrans_i_tb),
    .hsize_i     (hsize_i_tb),
    .hresp_o     (hresp_o_tb),
    .hreadyout_o (hreadyout_o_tb),
    .hrdata_o    (hrdata_o_tb),
    .otp_en_entropy_src_fw_read_i (caliptra_prim_mubi_pkg::MuBi8True),
    .otp_en_entropy_src_fw_over_i (caliptra_prim_mubi_pkg::MuBi8True),
    .rng_fips_o          (),
    .entropy_src_hw_if_i (entropy_src_hw_if_req),
    .entropy_src_hw_if_o (entropy_src_hw_if_rsp),
    .entropy_src_rng_o   (entropy_src_rng_req),
    .entropy_src_rng_i   (entropy_src_rng_rsp),
    .cs_aes_halt_o       (),
    .cs_aes_halt_i       (cs_aes_halt_rsp_t'('0)),
    .entropy_src_xht_o   (),
    .entropy_src_xht_i   (entropy_src_xht_rsp_t'('0)),
    .alert_rx_i          ('0),
    .alert_tx_o          (),
    .intr_es_entropy_valid_o      (),
    .intr_es_health_test_failed_o (),
    .intr_es_observe_fifo_ready_o (),
    .intr_es_fatal_err_o          ()
  );

  physical_rng #(
    .DutyCycle(1)
  ) physical_rng_i (
    .clk    (clk_tb),
    .enable (generate_rng && entropy_src_rng_req.rng_enable),
    .data   (entropy_src_rng_rsp.rng_b),
    .valid  (entropy_src_rng_rsp.rng_valid)
  );

`ifndef VERILATOR
  always begin
    #CLK_HALF_PERIOD clk_tb = !clk_tb;
  end
`endif

  task automatic init_sim;
    begin
      generate_rng        = 1'b0;
      entropy_src_hw_if_req = '0;
`ifndef VERILATOR
      clk_tb              = 1'b0;
`endif
      reset_n_tb          = 1'b0;
      haddr_i_tb          = '0;
      hwdata_i_tb         = '0;
      hsel_i_tb           = 1'b0;
      hwrite_i_tb         = 1'b0;
      hready_i_tb         = 1'b0;
      htrans_i_tb         = AHB_HTRANS_IDLE;
      hsize_i_tb          = 3'b011;
      read_data           = '0;
    end
  endtask

  task automatic reset_dut;
    begin
      reset_n_tb = 1'b0;
      repeat (2) @(posedge clk_tb);
      reset_n_tb = 1'b1;
      repeat (4) @(posedge clk_tb);
    end
  endtask

  task automatic write_single_word(input [31:0] address, input [31:0] word);
    begin
      hsel_i_tb   = 1'b1;
      haddr_i_tb  = address;
      hwdata_i_tb = word;
      hwrite_i_tb = 1'b1;
      hready_i_tb = 1'b1;
      htrans_i_tb = AHB_HTRANS_NONSEQ;
      hsize_i_tb  = 3'b010;

      @(posedge clk_tb);
      haddr_i_tb  = '0;
      hwrite_i_tb = 1'b0;
      htrans_i_tb = AHB_HTRANS_IDLE;
      wait (hreadyout_o_tb === 1'b1);

      @(posedge clk_tb);
      hsel_i_tb = 1'b0;
    end
  endtask

  task automatic read_single_word(input [31:0] address);
    begin
      hsel_i_tb   = 1'b1;
      haddr_i_tb  = address;
      hwrite_i_tb = 1'b0;
      hready_i_tb = 1'b1;
      htrans_i_tb = AHB_HTRANS_NONSEQ;
      hsize_i_tb  = 3'b010;

      @(posedge clk_tb);
      hwdata_i_tb = '0;
      haddr_i_tb  = '0;
      htrans_i_tb = AHB_HTRANS_IDLE;
      wait (hreadyout_o_tb === 1'b1);
      read_data   = hrdata_o_tb;

      @(posedge clk_tb);
      hsel_i_tb = 1'b0;
    end
  endtask

  task automatic wait_for_depth_at_least(input [6:0] target, input integer max_iters);
    integer iter;
    begin
      for (iter = 0; iter < max_iters; iter = iter + 1) begin
        read_single_word(ADDR_OBSERVE_FIFO_DEPTH);
        if (read_data[6:0] >= target) begin
          return;
        end
        repeat (4) @(posedge clk_tb);
      end

      $display("ERROR: Timed out waiting for observe FIFO depth >= %0d, last depth=%0d",
               target, read_data[6:0]);
      $fatal(1);
    end
  endtask

  task automatic drain_observe_fifo;
    integer iter;
    begin
      for (iter = 0; iter < 96; iter = iter + 1) begin
        read_single_word(ADDR_OBSERVE_FIFO_DEPTH);
        if (read_data[6:0] == 7'd0) begin
          return;
        end
        read_single_word(ADDR_FW_OV_RD_DATA);
      end

      $display("ERROR: Timed out draining observe FIFO, last depth=%0d", read_data[6:0]);
      $fatal(1);
    end
  endtask

  initial begin
    $display("Starting entropy_src FW override overflow hold test");

    init_sim();
    reset_dut();

    write_single_word(ADDR_CONF, 32'h02649999);
    write_single_word(ADDR_FW_OV_CONTROL, 32'h00000096);
    write_single_word(ADDR_MODULE_ENABLE, 32'h00000006);

    generate_rng = 1'b1;
    wait_for_depth_at_least(7'd64, 4000);
    repeat (64) @(posedge clk_tb);

    generate_rng = 1'b0;
    repeat (256) @(posedge clk_tb);

    read_single_word(ADDR_OBSERVE_FIFO_DEPTH);
    if (read_data[6:0] !== 7'd64) begin
      $display("ERROR: Observe FIFO depth should remain full before draining, got %0d",
               read_data[6:0]);
      $fatal(1);
    end

    repeat (4) begin
      read_single_word(ADDR_FW_OV_RD_FIFO_OVERFLOW);
      if (read_data[0] !== 1'b1) begin
        $display("ERROR: Overflow status did not stay asserted while FIFO remained full");
        $fatal(1);
      end
    end

    drain_observe_fifo();
    read_single_word(ADDR_OBSERVE_FIFO_DEPTH);
    if (read_data[6:0] !== 7'd0) begin
      $display("ERROR: Observe FIFO did not drain to empty, got %0d", read_data[6:0]);
      $fatal(1);
    end

    generate_rng = 1'b1;
    wait_for_depth_at_least(7'd4, 512);
    generate_rng = 1'b0;
    repeat (64) @(posedge clk_tb);

    read_single_word(ADDR_FW_OV_RD_FIFO_OVERFLOW);
    if (read_data[0] !== 1'b0) begin
      $display("ERROR: Overflow status did not clear after FIFO drain and refill restart");
      $fatal(1);
    end

    $display("* TESTCASE PASSED");
    $finish;
  end
endmodule
TBEOF

cat > "${tb_cpp}" <<'CPPEOF'
