  Verilated::commandArgs(argc, argv);

  auto* tb = new Ventropy_src_fw_ov_overflow_tb;

  while (!Verilated::gotFinish()) {
    main_time += 5;
    tb->clk_tb = !tb->clk_tb;
    tb->eval();
  }

  delete tb;
  return EXIT_SUCCESS;
}
CPPEOF

grep -v 'src/entropy_src/tb/entropy_src_tb.sv' src/entropy_src/config/entropy_src_tb.vf > "${tb_vf}"
printf '%s\n' "${tb_sv}" >> "${tb_vf}"

run_status=0
set +e
pushd "${scratch_dir}" >/dev/null
verilator --cc \
  --timing \
