  --top-module "${tb_top}" \
  -Mdir obj_dir \
  -exe "${tb_cpp}"
run_status=$?
if [[ ${run_status} -eq 0 ]]; then
  make -j"$(nproc)" -C obj_dir -f "V${tb_top}.mk" OPT_FAST="-Os" VM_PARALLEL_BUILDS=1
  run_status=$?
fi
if [[ ${run_status} -eq 0 ]]; then
  "./obj_dir/V${tb_top}"
  run_status=$?
fi
popd >/dev/null
set -e

echo "HWE_BENCH_RESULTS_START"
if [[ ${run_status} -eq 0 ]]; then
  echo "TEST: entropy_src_fw_ov_overflow_hold ... PASS"
else
  echo "TEST: entropy_src_fw_ov_overflow_hold ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "${run_status}"
